UPDATE sys_wechat_profile
SET nickname = #{nickname},
    profile_updated_at = #{now},
    updated_at = #{now}
WHERE employee_id = #{employeeId}

UPDATE sys_wechat_profile
SET avatar_object_key = #{avatarObjectKey},
    avatar_url = NULL,
    profile_updated_at = #{now},
    updated_at = #{now}
WHERE employee_id = #{employeeId}
